local Rayfield = loadstring(game:HttpGet("https://sirius.menu/rayfield"))()

local Window = Rayfield:CreateWindow({
	Name = "Lucky Block UI",
	LoadingTitle = "Loading...",
	LoadingSubtitle = "By You",
	ConfigurationSaving = {
		Enabled = false
	}
})

local Tab = Window:CreateTab("Main", 4483362458)

Tab:CreateButton({
	Name = "Spawn Lucky Block",
	Callback = function()
		game:GetService("ReplicatedStorage"):WaitForChild("SpawnLuckyBlock"):FireServer()
	end
})

Tab:CreateButton({
	Name = "Spawn Rainbow Block",
	Callback = function()
		game:GetService("ReplicatedStorage"):WaitForChild("SpawnRainbowBlock"):FireServer()
	end
})

Tab:CreateButton({
	Name = "Buy Yellow Button Seed",
	Callback = function()
		local args = {
			"Yellow Button Seed",
			0
		}
		game:GetService("ReplicatedStorage"):WaitForChild("BuySeedRequest"):FireServer(unpack(args))
	end
})

Tab:CreateButton({
	Name = "Spawn Yellow Button Seed",
	Callback = function()
		local args = {
			"Yellow Button Seed",
			0
		}
		game:GetService("ReplicatedStorage"):WaitForChild("BuySeedRequest"):FireServer(unpack(args))
	end
})

Tab:CreateButton({
	Name = "Spawn Brown Mushroom Seed",
	Callback = function()
		local args = {
			"Brown Mushroom Seed",
			0
		}
		game:GetService("ReplicatedStorage"):WaitForChild("BuySeedRequest"):FireServer(unpack(args))
	end
})
